"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5633],{11976:e=>{e.exports=JSON.parse('{"functions":[{"name":"flip","desc":"Flips the table\'s keys with its values.\\nIf `mergeDuplicates` is `true`, All values will be stored in a table at the key\'s index, instead of overwriting them.\\n\\n#### Example:\\n```lua\\nTableUtil.flip({ a = 1, b = 2 }) -- { [1] = \\"a\\", [2] = \\"b\\" }\\nTableUtil.flip({ a = 1, b = 2 }, true) -- { [1] = { \\"a\\" }, [2] = { \\"b\\" } }\\n\\n-- Use case: finding all keys with the same value\\nlocal newTable = TableUtil.flip({ a = 1, b = 2, c = 2 }, true) -- { [1] = { \\"a\\" }, [2] = { \\"b\\", \\"c\\" } }\\nprint(#newTable[2]) -- 2\\n```","params":[{"name":"source","desc":"The table you want to flip","lua_type":"{ [any]: any }"},{"name":"mergeDuplicates","desc":"Merge key duplicates into a table instead of overwriting them.","lua_type":"boolean?"}],"returns":[{"desc":"","lua_type":"{ [any]: any }"}],"function_type":"static","source":{"line":44,"path":"src/TableUtil.luau"}},{"name":"map","desc":"Maps a table or instance to a new table.\\n\\n#### Example:\\n```lua\\nTableUtil.map({ 1, 2, 3 }, function(v)\\n\\treturn v * 2\\nend) -- { 2, 4, 6 }\\n\\nTableUtil.map({ 1, 2, 3 }, function(v, i)\\n\\treturn i * 2\\nend) -- { 2, 4, 6 }\\n```","params":[{"name":"source","desc":"The table you want to map","lua_type":"{ [any]: any }"},{"name":"callbackFn","desc":"The function to map the table with","lua_type":"(any, any, any) -> (any, any)"}],"returns":[{"desc":"","lua_type":"{ [any]: any }"}],"function_type":"static","source":{"line":89,"path":"src/TableUtil.luau"}},{"name":"filter","desc":"Filters a table, or an Instance\'s children, into a new array.\\n\\n#### Example:\\n```lua\\nlocal noTwo = TableUtil.filter({ 1, 2, 3 }, function(value)\\n\\treturn value ~= 2\\nend) -- { 1, 3 }\\n\\nlocal parts = TableUtil.filter(workspace, function(value)\\n\\treturn value:IsA(\\"Part\\")\\nend) -- { Part, Part2 }\\n```","params":[{"name":"source","desc":"The table you want to filter","lua_type":"{ [any]: any } | Instance"},{"name":"callbackFn","desc":"The function to filter the table with (element, index, source). Keeps elements it returns exactly `true` for.","lua_type":"(any, any, any) -> (boolean?)"}],"returns":[{"desc":"","lua_type":"{ any }"}],"function_type":"static","source":{"line":139,"path":"src/TableUtil.luau"}},{"name":"mapIndex","desc":"Maps an array to a new table. The callback can return a new value, and optionally\\na new key to store it under; otherwise each value keeps its position.\\n\\n#### Example:\\n```lua\\nTableUtil.mapIndex({ 1, 2, 3 }) -- { [1] = 1, [2] = 2, [3] = 3 }\\n\\nTableUtil.mapIndex({ 1, 2, 3 }, function(v)\\n\\treturn v * 2\\nend) -- { [1] = 2, [2] = 4, [3] = 6 }\\n\\nTableUtil.mapIndex({ \\"a\\", \\"b\\" }, function(v, i)\\n\\treturn i, v\\nend) -- { a = 1, b = 2 }\\n```","params":[{"name":"source","desc":"The array you want to map","lua_type":"{ any }"},{"name":"filterFn","desc":"Returns the new value and, optionally, the new key","lua_type":"((value: any, index: number, source: { any }) -> (any?, any?))?"}],"returns":[{"desc":"","lua_type":"{ [any]: any }"}],"function_type":"static","source":{"line":183,"path":"src/TableUtil.luau"}},{"name":"trimWhitespace","desc":"Trims leading and trailing whitespace from a string.\\n\\n#### Example:\\n```lua\\nTableUtil.trimWhitespace(\\"  Hello, world!  \\") -- \\"Hello, world!\\"\\n```","params":[{"name":"text","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"string"}],"function_type":"static","source":{"line":222,"path":"src/TableUtil.luau"}},{"name":"trimLeadingWhitespace","desc":"Trims leading whitespace from a string.\\n\\n#### Example:\\n```lua\\nTableUtil.trimLeadingWhitespace(\\"  Hello, world!\\") -- \\"Hello, world!\\"\\n```","params":[{"name":"text","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"string"}],"function_type":"static","source":{"line":240,"path":"src/TableUtil.luau"}},{"name":"trimTrailingWhitespace","desc":"Trims trailing whitespace from a string.\\n\\n#### Example:\\n```lua\\nTableUtil.trimTrailingWhitespace(\\"Hello, world!  \\") -- \\"Hello, world!\\"\\n```","params":[{"name":"text","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"string"}],"function_type":"static","source":{"line":258,"path":"src/TableUtil.luau"}},{"name":"split","desc":"Splits a string into a table of strings using a delimiter.\\nIf `delimiter` is not provided, it defaults to a space.\\n\\nSetting `trimTrailingDelimiter` to `false` will result in an empty string at the end of the table if the text ends with the delimiter\\n\\nSetting `trim` to `false` will result in whitespace not being trimmed from each chunk\\n\\n#### Example:\\n```lua\\nTableUtil.split(\\"Hello, world!\\") -- { \\"Hello,\\", \\"world!\\" }\\nTableUtil.split(\\"Hello, world!\\", \\", \\") -- { \\"Hello\\", \\"world!\\" }\\nTableUtil.split(\\"Hello, world!\\", \\",\\", nil, false) -- { \\"Hello\\", \\" world!\\" } -- no whitespace is trimmed\\nTableUtil.split(\\"Hello, world!,\\", \\",\\", false) -- { \\"Hello\\", \\"world!\\", \\"\\" } -- trailing delimiter is included\\n\\nTableUtil.split(\\"path/to/file\\", \\"/\\") -- { \\"path\\", \\"to\\", \\"file\\" }\\nTableUtil.split(\\"path/to/file/\\", \\"/\\") -- { \\"path\\", \\"to\\", \\"file\\" } -- trailing delimiter is trimmed\\n```","params":[{"name":"text","desc":"","lua_type":"string | number?"},{"name":"delimiter","desc":"","lua_type":"string?"},{"name":"trimTrailingDelimiter","desc":"","lua_type":"boolean?"},{"name":"trim","desc":"Trim whitespace from each chunk","lua_type":"boolean?"}],"returns":[{"desc":"","lua_type":"{ string }"}],"function_type":"static","source":{"line":290,"path":"src/TableUtil.luau"}},{"name":"join","desc":"Joins an array of strings and numbers into a single string, with `separator`\\nbetween each element.\\n\\n#### Example:\\n```lua\\nTableUtil.join({ \\"Hello\\", \\"world!\\" }, \\",\\") -- \\"Hello,world!\\"\\nTableUtil.join({ \\"Hello\\", \\"world!\\" }, \\", \\") -- \\"Hello, world!\\"\\n```","params":[{"name":"stringTable","desc":"The table you want to join","lua_type":"{ [any]: string | number }"},{"name":"separator","desc":"The separator to use when joining the table. Defaults to `\\",\\"`.","lua_type":"string?"}],"returns":[{"desc":"","lua_type":"string"}],"function_type":"static","source":{"line":378,"path":"src/TableUtil.luau"}},{"name":"extend","desc":"Extends a table with one or more tables, in order, and returns it. The target\\ntable is modified in place.\\n\\n#### Example:\\n```lua\\nTableUtil.extend({ a = 1 }, { b = 2 }, { c = 3 }) -- { a = 1, b = 2, c = 3 }\\nTableUtil.extend({ a = 1 }, { a = 2 }, { a = 3 }) -- { a = 3 } -- Last argument overwrites previous arguments\\nTableUtil.extend({ a = 1 }, { a = 2 }, { a = 3 }, true) -- Error: Argument #3 must be a table\\n```\\n\\n#### Config override example:\\n```lua\\nlocal function getDefaultConfig()\\n\\treturn {\\n\\t\\thealth = 100\\n\\t}\\nend\\n\\nlocal buffConfig = {\\n\\thealth = 150,\\n\\tspeed = 1.5\\n}\\n\\nlocal playerConfig: { [any]: any } = TableUtil.extend(getDefaultConfig(), buffConfig) -- { health = 150, speed = 1.5 }\\n```\\n\\nPass `true` as the first argument for deep mode, in which case the target table\\nis the second argument. Note that nested tables are currently assigned by\\nreference rather than merged key by key.","params":[{"name":"arg1","desc":"The target table, or `true` for deep mode","lua_type":"boolean | { [any]: any }"},{"name":"arg2","desc":"The first table to merge in, or the target table in deep mode","lua_type":"{ [any]: any }"},{"name":"...","desc":"The tables you want to merge into the target table","lua_type":"{ [any]: any }"}],"returns":[{"desc":"","lua_type":"{ [any]: any }"}],"function_type":"static","source":{"line":439,"path":"src/TableUtil.luau"}},{"name":"assign","desc":"The assign function copies all properties from one or more source objects to a target object.\\n\\nAlias for `TableUtil.extend`.","params":[{"name":"targetTable","desc":"The target table you want to assign values to","lua_type":"{ [any]: any }"},{"name":"...","desc":"The tables you want to merge into the target table","lua_type":"{ [any]: any }"}],"returns":[{"desc":"","lua_type":"{ [any]: any }"}],"function_type":"static","source":{"line":472,"path":"src/TableUtil.luau"}},{"name":"treePath","desc":"Gets a value from a table or Instance using a path.\\n\\n#### Example:\\n```lua\\nTableUtil.treePath({ a = { b = { c = 1 } } }, \\"a.b.c\\") -- 1\\nTableUtil.treePath({ a = { b = { c = 1 } } }, \\"a.b\\") -- { c = 1 }\\nTableUtil.treePath(game.Workspace, \\"House.Door\\") -- Door instance\\nTableUtil.treePath(script, \\"NonexistantChild\\") -- nil\\n```","params":[{"name":"tree","desc":"The table or instance you want to get the value from","lua_type":"{ [any]: any } | Instance"},{"name":"path","desc":"The path to the value","lua_type":"string"},{"name":"delimiter","desc":"The delimiter to use when splitting the path","lua_type":"string?"}],"returns":[{"desc":"","lua_type":"any"}],"function_type":"static","source":{"line":493,"path":"src/TableUtil.luau"}},{"name":"insertIf","desc":"Inserts a value into a table if the test condition is true.\\n\\n#### Example:\\n```lua\\nTableUtil.insertIf({ 1, 2, 3 }, 4, true) -- { 1, 2, 3, 4 }\\nTableUtil.insertIf({ 1, 2, 3 }, 4, false) -- { 1, 2, 3 }\\nTableUtil.insertIf({ 1, 2, 3 }, 4, function()\\n\\treturn true\\nend) -- { 1, 2, 3, 4 }\\n```","params":[{"name":"target","desc":"The table you want to insert the value into","lua_type":"{ [any]: any }"},{"name":"value","desc":"The value you want to insert","lua_type":"any"},{"name":"condition","desc":"The test condition","lua_type":"nil | boolean | () -> boolean?"}],"returns":[{"desc":"","lua_type":"nil"}],"function_type":"static","source":{"line":543,"path":"src/TableUtil.luau"}},{"name":"instanceChildrenToTable","desc":"Collects all children of an instance into a table.\\n\\n#### Example:\\n```lua\\nTableUtil.instanceChildrenToTable(game.Workspace) -- { Part = Instance, Part2 = Instance }\\nTableUtil.instanceChildrenToTable(game.ReplicatedStorage.Config) -- { Config1 = CFrameValue, Config2 = StringValue }\\n```","params":[{"name":"instance","desc":"The instance you want to collect children from","lua_type":"Instance"}],"returns":[{"desc":"","lua_type":"{ [string]: Instance }"}],"function_type":"static","source":{"line":573,"path":"src/TableUtil.luau"}},{"name":"tableLength","desc":"Returns the total amount of values in a table.\\n\\n#### Example:\\n```lua\\nTableUtil.tableLength({ 1, 2, 3 }) -- 3\\nTableUtil.tableLength({ a = 1, b = 2, c = 3 }) -- 3\\n```","params":[{"name":"source","desc":"","lua_type":"{ [any]: any }"}],"returns":[{"desc":"","lua_type":"number"}],"function_type":"static","source":{"line":598,"path":"src/TableUtil.luau"}},{"name":"tableRandomIndex","desc":"Returns a random index from a table or instance.\\n\\n#### Example:\\n```lua\\nTableUtil.tableRandomIndex({ 1, 2, 3 }) -- 2\\nTableUtil.tableRandomIndex({ a = 1, b = 2, c = 3 }) -- \\"b\\"\\n```","params":[{"name":"obj","desc":"The table or instance you want to get a random index from","lua_type":"{ [any]: any } | Instance"}],"returns":[{"desc":"","lua_type":"any"}],"function_type":"static","source":{"line":623,"path":"src/TableUtil.luau"}},{"name":"indexOf","desc":"Returns the key of the first value equal to `value`, or 0 if there is none.\\n\\n```lua\\nTableUtil.indexOf({ \\"a\\", \\"b\\", \\"c\\" }, \\"b\\") -- 2\\nTableUtil.indexOf({ \\"a\\", \\"b\\", \\"c\\" }, \\"z\\") -- 0\\n```","params":[{"name":"obj","desc":"","lua_type":"{ [any]: any }"},{"name":"value","desc":"","lua_type":"any"}],"returns":[{"desc":"","lua_type":"any"}],"function_type":"static","source":{"line":651,"path":"src/TableUtil.luau"}},{"name":"tableRandom","desc":"Returns a random value from a table, or a random child of an Instance.\\n\\n```lua\\nTableUtil.tableRandom({ \\"a\\", \\"b\\", \\"c\\" }) -- \\"b\\"\\nTableUtil.tableRandom({ x = 1, y = 2 }) -- 2\\n```","params":[{"name":"obj","desc":"The table or Instance to select from.","lua_type":"{ [any]: any } | Instance"}],"returns":[{"desc":"nil if the table is empty.","lua_type":"any"}],"function_type":"static","source":{"line":676,"path":"src/TableUtil.luau"}},{"name":"makeConfigFromValues","desc":"Creates a nested table of value instances from a Folder or Configuration instance.\\n\\n#### Example:\\n\\n- Config (Folder) -- in ReplicatedStorage\\n  - Origin (CFrameValue), Value = CFrame.new(0, 1, 0)\\n  - WelcomeMessage (StringValue), Value = \\"Hello, world!\\"\\n\\n```lua\\nTableUtil.makeConfigFromValues(game.ReplicatedStorage.Config)\\n```\\n\\nResult:\\n```lua\\n{\\n\\tOrigin = CFrame.new(0, 1, 0),\\n\\tWelcomeMessage = \\"Hello, world!\\"\\n}\\n```","params":[{"name":"folder","desc":"The folder or Configuration you want to make a table from","lua_type":"Folder | Configuration"}],"returns":[{"desc":"","lua_type":"{ [string]: any }"}],"function_type":"static","source":{"line":710,"path":"src/TableUtil.luau"}},{"name":"tableRemove","desc":"Removes elements from an array in place, shifting the remaining elements down.\\n\\n#### Example:\\n```lua\\nlocal list = { \\"a\\", \\"b\\", \\"c\\" }\\nTableUtil.tableRemove(list, 2) -- list is now { \\"a\\", \\"c\\" }\\n\\nlocal values = { 1, 2, 3, 2 }\\nTableUtil.tableRemove(values, { 2 }) -- values is now { 1, 3 }\\n```","params":[{"name":"obj","desc":"The array you want to remove elements from","lua_type":"{ any }"},{"name":"removeTest","desc":"The index to remove, or a list of values to remove","lua_type":"number | { any }"}],"returns":[{"desc":"","lua_type":"nil"}],"function_type":"static","source":{"line":748,"path":"src/TableUtil.luau"}}],"properties":[],"types":[],"name":"TableUtil","desc":"Table and string helpers: flipping, mapping, filtering and merging tables, reading\\npaths through nested tables or Instances, splitting and joining strings, and\\nrandom picks.","source":{"line":9,"path":"src/TableUtil.luau"}}')}}]);